    crate::testport::assert_eq(crate::port::cells_len(rq), 0, "no request");
    let plan2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rq2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    plan_of(plan2, 1, pk_scan());
